n    <!-- SPECIALIZATION TRACKS SECTION -->\r\n    <section class=\"container course-body-section\" id=\"specialization-tracks-section\" style=\"display:none;\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">SPECIALIZATION PATHWAYS</span>\r\n        <h2 class=\"section-title\">Choose Your <span class=\"gradient-text\">Focus Track</span></h2>\r\n      </div>\r\n      <div id=\"specialization-tracks-container\" style=\"max-width:860px;\">\r\n        <!-- Populated by JS -->\r\n      </div>\r\n    </section>\r\n\r\n    <!-- TARGET AUDIENCE & PREREQUISITES SECTION -->\r\n    <section class=\"container course-body-section\" id=\"audience-section\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">ELIGIBILITY & AUDIENCE</span>\r\n        <h2 class=\"section-title\">Who Is This Program <span class=\"gradient-text\">Built For?</span></h2>\r\n      </div>\r\n\r\n      <div id=\"audience-container\" style=\"max-width:860px;\">\n        <div class=\"audience-grid\">\n        <div class=\"audience-card best-for\">\n          <h3><span style=\"color:var(--green)\">✓</span> Ideal For (Best For)</h3>\n          <ul class=\"audience-list\">\n            <li><span class=\"bullet-icon\">✓</span><span>Aspiring digital marketing professionals.</span></li><li><span class=\"bullet-icon\">✓</span><span>Entrepreneurs wanting to scale their businesses online.</span></li><li><span class=\"bullet-icon\">✓</span><span>Freelancers looking to offer high-demand digital services.</span></li>\n          </ul>\n        </div>\n        \n          <div class=\"audience-card not-for\">\n            <h3><span style=\"color:var(--orange)\">✕</span> Who Is This NOT For</h3>\n            <ul class=\"audience-list\">\n              <li><span class=\"bullet-icon\">✕</span><span>Those looking for passive, theoretical lectures without hands-on implementation.</span></li><li><span class=\"bullet-icon\">✕</span><span>Students expecting get-rich-quick schemes.</span></li>\n            </ul>\n          </div>\n        \n      </div>\n      </div>\r\n\r\n      <div id=\"prerequisites-container\" style=\"max-width:860px;\">\n        <div class=\"prerequisites-box\">\n        <div class=\"prereq-item\">\n          <h4>Required Prerequisites</h4>\n          <p>Basic computer and internet literacy</p>\n        </div>\n        <div class=\"prereq-item\">\n          <h4>Recommended Background</h4>\n          <p>Familiarity with social media platforms</p>\n        </div>\n      </div>\n      </div>\r\n    </section>\r\n\r\n    <!-- LEARNING OUTCOMES SECTION -->\r\n    <section class=\"container course-body-section\" id=\"outcomes-section\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">LEARNING OUTCOMES</span>\r\n        <h2 class=\"section-title\">Action-Oriented <span class=\"gradient-text\">Competencies You Gain</span></h2>\r\n      </div>\r\n\r\n      <div id=\"outcomes-container\" style=\"max-width:860px;\">\n        <div class=\"outcomes-grid\">\n        \n            <div class=\"outcome-item\">\n              <span class=\"outcome-verb-badge\">STRATEGIZE</span>\n              <p class=\"outcome-text\">Develop comprehensive marketing plans based on business goals.</p>\n            </div>\n          \n            <div class=\"outcome-item\">\n              <span class=\"outcome-verb-badge\">EXECUTE</span>\n              <p class=\"outcome-text\">Launch and manage campaigns across relevant digital channels.</p>\n            </div>\n          \n            <div class=\"outcome-item\">\n              <span class=\"outcome-verb-badge\">MEASURE</span>\n              <p class=\"outcome-text\">Implement tracking and reporting to accurately attribute conversions.</p>\n            </div>\n          \n            <div class=\"outcome-item\">\n          